import pandas as pd
import matplotlib.pyplot as plt
from sklearn.preprocessing import MinMaxScaler

# Constants
PLOT_TITLE = "Scaled Values"


def task_func(data_dict):
    if not isinstance(data_dict, dict):
        raise TypeError("data_dict must be a dictionary.")

    fig, ax = plt.subplots()
    ax.set_title(PLOT_TITLE)
    ax.set_xlabel("Key")
    ax.set_ylabel("Scaled Value")

    if not data_dict:
        return pd.DataFrame(), ax

    values = list(data_dict.values())

    if all(pd.api.types.is_scalar(v) for v in values):
        df = pd.DataFrame({"value": pd.Series(values, index=list(data_dict.keys()))})
    else:
        normalized = {}
        target_len = 0

        for key, value in data_dict.items():
            if pd.api.types.is_scalar(value):
                normalized[key] = value
            elif isinstance(value, dict):
                raise ValueError(
                    "data_dict values must be numeric scalars or one-dimensional sequences."
                )
            else:
                try:
                    seq = list(value)
                except TypeError as exc:
                    raise ValueError(
                        "data_dict values must be numeric scalars or one-dimensional sequences."
                    ) from exc
                normalized[key] = seq
                target_len = max(target_len, len(seq))

        if target_len == 0:
            target_len = 1

        for key, value in list(normalized.items()):
            if pd.api.types.is_scalar(value):
                normalized[key] = [value] * target_len
            else:
                seq = list(value)
                if len(seq) < target_len:
                    seq = seq + [pd.NA] * (target_len - len(seq))
                normalized[key] = seq

        try:
            df = pd.DataFrame(normalized)
        except Exception as exc:
            raise ValueError("data_dict must form a rectangular table of numeric values.") from exc

    try:
        df = df.apply(pd.to_numeric, errors="raise")
    except Exception as exc:
        raise ValueError("data_dict must contain only numeric values.") from exc

    if df.isna().any().any():
        raise ValueError("data_dict contains missing or irregular values.")

    scaler = MinMaxScaler()
    scaled_df = pd.DataFrame(
        scaler.fit_transform(df),
        index=df.index,
        columns=df.columns,
    )

    x_values = scaled_df.index.astype(str)
    if scaled_df.shape[1] == 1:
        ax.plot(x_values, scaled_df.iloc[:, 0].values, marker="o")
    else:
        for column in scaled_df.columns:
            ax.plot(x_values, scaled_df[column].values, marker="o", label=str(column))
        ax.legend()

    fig.tight_layout()
    return scaled_df, ax
